contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We need to send Ether to c to trigger Deposit; take depositAmt as parameter.
    receive() external payable {}

    function run(uint depositAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmt)); require(depositAmt <= 1000000000000000000000000000000);
        // ensure this test contract has enough balance to send depositAmt
        require(address(this).balance >= depositAmt);

        // read balance before
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.Deposit{value: depositAmt}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;

        // General rule: if Deposit did not revert, then balAfter == balBefore + depositAmt;
        // if it reverted, balAfter == balBefore.
        assert((!reverted && balAfter == balBefore + depositAmt) || (reverted && balAfter == balBefore));
    }
}

